import json
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class DeltaFileOperations:
    def __init__(self):
        self.delta_json_content = None
        self.output_delta_file = None

    def fetch_delta_content(self, delta_jsonfile):
        """
        Function fetches delta content

        :param delta_jsonfile: str, Path to delta json file

        :returns parsed delta json content
        :rtype json
        """
        self.output_delta_file = delta_jsonfile.replace(".json", "_autocorrected_file.json")
        logger.info("Fetching Delta content")
        with open(delta_jsonfile) as delta_file:
            self.delta_json_content = json.load(delta_file)
        logger.debug("Successfully fetched Delta content {} \n #########################################".format(
            self.delta_json_content))
        return self.delta_json_content

    def fetch_updated_delta_content(self, delta):
        """
        Function fetches updated delta content

        :param delta: dict, delta file to fetch the content

        :returns Updated delta content
        :rtype json object
        """
        delta_content = {}
        for delta_param in delta['parameters']:
            if delta_param['value'] is None:
                delta_content[delta_param['parameterName']] = None
            elif self._is_complex_type(delta_param['value']):
                if isinstance(delta_param['value'][0], dict):
                    delta_content[delta_param['parameterName']] = list(delta_param['value'][0].keys())
                elif isinstance(delta_param['value'][0], str) or isinstance(delta_param['value'][0].encode('utf-8'),
                                                                            str):
                    delta_content[delta_param['parameterName']] = None
            elif self._is_simple_type(delta_param['value']):
                delta_content[delta_param['parameterName']] = None
            else:
                logger.warn("{} Type is not Handled".format(type(delta_param['value'])))
        return delta_content

    def remove_parameter_from_delta(self, delta, parameter_dict):
        """
        Function to remove parameters from delta file

        :param delta: dict, Delta moc from where parameter_dict to be removed
        :param parameter_dict: dict, Parameters identified to be removed

        :returns None
        :rtype NA
        """
        for remove_param in parameter_dict:
            if parameter_dict[remove_param] is None:
                for i, each_delta_param in enumerate(delta['parameters']):
                    if each_delta_param['parameterName'] == remove_param:
                        delta['parameters'].pop(i)
                self.write_to_json_file(input_file=self.delta_json_content, output_file=self.output_delta_file)
            else:
                for item in parameter_dict[remove_param]:
                    for i, each_delta_param in enumerate(delta['parameters']):
                        if each_delta_param['parameterName'] == remove_param:
                            del delta['parameters'][i]['value'][0][item]
                            if delta['parameters'][i]['value'] == [{}]:
                                del delta['parameters'][i]
                self.write_to_json_file(input_file=self.delta_json_content, output_file=self.output_delta_file)

    def update_delta_content(self, delta, parameter_content):
        """
        Function to update delta content

        :param delta: dict, Delta moc content to which given parameter needs to be added
        :param parameter_content: dict, Full structure of the parameter to be added

        :returns None
        :rtype NA
        """
        new_parameter = True
        param_pos = None
        for index, pos in enumerate(delta['parameters']):
            if pos['parameterName'] == parameter_content['parameterName']:
                param_pos = index
                new_parameter = False
        if new_parameter:
            delta['parameters'].append(parameter_content)
        else:
            delta['parameters'][param_pos]['value'][0][next(iter(parameter_content["value"][0]))] = \
                next(iter(parameter_content["value"][0].values()))
        logger.info("New dict to be added {}".format(parameter_content))

    def write_to_json_file(self, input_file, output_file):
        new_filename = output_file + ".json"
        open(output_file, "w").write(json.dumps(input_file))
        # return output_file

    def _is_simple_type(self, parameter_value):
        """
        Function to check if given parameter value is of type simple

        :param parameter_value: value of the parameter to decide the type

        :returns True, if simple, else False
        :rtype boolean
        """
        return isinstance(parameter_value, int) or isinstance(parameter_value, float) or \
               isinstance(parameter_value, str) or isinstance(parameter_value.encode('utf-8'), str)

    def _is_complex_type(self, parameter_value):
        """
        Function to check if given parameter value is of type complex

        :param parameter_value: value of the parameter to decide the type

        :returns True, if complex, else False
        :rtype boolean
        """
        return isinstance(parameter_value, list)
